 Dictionary<string,List<BackupDemand>> SourcesByItem(List<BackupDemand> demands,out List<BackupDemand> unmapped){var result=new Dictionary<string,List<BackupDemand>>();unmapped=new List<BackupDemand>();var targets=backupBill.Select(b=>b.Target).ToList();foreach(var d in demands){string slot;BackupTarget target;/* owner (19 November 2026, "kapag nagseselect ako kung saan imamap di naalis sa status"): the BACKUP item chosen in the app wins over the app's own target */string chosen;if(!d.ManualOverride&&boqUnmapped.Contains(d.Key))target=null;/* left unmapped by hand */else if(!d.ManualOverride&&boqRouteOverrides.TryGetValue(d.Key,out chosen)&&chosen!=null&&targets.Any(t=>t.SlotId==chosen))target=targets.First(t=>t.SlotId==chosen);else if(d.TargetSlotId!=null)target=BackupMapping.ResolveTarget(d,targets)??(backupBillRoutes.TryGetValue(d.Key,out slot)?targets.FirstOrDefault(t=>t.SlotId==slot):null);else if(backupBillRoutes.TryGetValue(d.Key,out slot))target=targets.FirstOrDefault(t=>t.SlotId==slot);else target=boqUnmapped.Contains(d.Key)||BackupMapping.IsPainting(d)?null:BackupMapping.Suggest(d,targets);if(target==null){/* v1.19.2: a quantity that is not mapped cannot be excluded from a pay item; it was zeroed and vanished
   from both the BOQ and the Not mapped list. It is listed with its quantity and its exclusion is cleared. */double excludedQuantity;if(boqExcludedQuantities.TryGetValue(d.Key,out excludedQuantity)){d.Quantity=excludedQuantity;boqExcludedQuantities.Remove(d.Key);boqIncludes.Remove(d.Key);}
   if(d.Quantity>1e-10||d.ManualOverride)unmapped.Add(d);continue;}List<BackupDemand> rows;if(!result.TryGetValue(target.SlotId,out rows)){rows=new List<BackupDemand>();result[target.SlotId]=rows;}rows.Add(d);}return result;}
 void AddUnmappedBoqRows(IEnumerable<BackupDemand> items){var rows=items.Where(q=>!q.ManualOverride).ToList();if(rows.Count==0)return;int section=boqGrid.Rows.Add("","COMPUTED QUANTITIES — SELECT BACKUP PAY ITEM ONCE","","");boqGrid.Rows[section].ReadOnly=true;boqGrid.Rows[section].DefaultCellStyle.BackColor=PremiumControls.AccentSoft;foreach(var q in rows){int n=boqGrid.Rows.Add("",q.Description,q.Quantity.ToString("0.########",CultureInfo.InvariantCulture),q.Unit);boqGrid.Rows[n].ReadOnly=true;boqGrid.Rows[n].Tag=q;string branch="unmapped:"+q.Key;boqGrid.Rows[n].Cells[1].ToolTipText="Computed quantity is retained in Tool Kit. Use Map BACKUP items for an ambiguous/new specification; the app does not guess among duplicate pay items.";foreach(var source in q.Sources){var detail=new DataGridViewRow();detail.CreateCells(boqGrid,"","    "+source.Description,source.Quantity.ToString("0.########",CultureInfo.InvariantCulture),source.Unit);detail.ReadOnly=true;detail.DefaultCellStyle.ForeColor=PowTheme.Muted;BoqDisclosure.Parent(boqGrid.Rows[n],branch);BoqDisclosure.Detail(detail,branch);boqGrid.Rows.Add(detail);}}}
 void UpdateBackupBillDashboard(){var selected=boqGrid.CurrentRow==null?null:boqGrid.CurrentRow.Tag as BackupBillItem;string selectedId=selected==null?null:selected.Slot;var scroll=BoqScrollState.Capture(boqGrid);bool selectedVisible=boqGrid.CurrentRow!=null&&boqGrid.CurrentRow.Displayed;EnsureBoqIncludeColumn();paintingBackupBill=true;var rowSizing=boqGrid.AutoSizeRowsMode;boqGrid.SuspendLayout();boqGrid.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.None;try{boqGrid.Rows.Clear();var pendingRows=new List<DataGridViewRow>();boqCurrentPart=null;boqStatusNotes.Clear();bool blankCatalogue=!HasMeasuredInputs()&&backupBill.All(b=>!b.ManualQuantity.HasValue&&!b.WorkbookQuantity.HasValue)&&!ManualBoqQuantities().Any();var demands=(blankCatalogue?new List<BackupDemand>():BackupQuantities(false)).Where(d=>d.Quantity>1e-10||d.ManualOverride||d.Sources.Any(s=>s.Quantity>1e-10)||backupBillRoutes.ContainsKey(d.Key)).ToList();List<BackupDemand> unmapped;var grouped=SourcesByItem(demands,out unmapped);foreach(var item in backupBill){AddBoqPartHeading(item,pendingRows);List<BackupDemand> sources;if(!grouped.TryGetValue(item.Slot,out sources))sources=new List<BackupDemand>();var matching=sources.Where(d=>BackupMapping.Unit(d.Unit)==BackupMapping.Unit(item.Unit)).ToList();bool suggested=matching.Any(IsGeneralSuggestion);/* Part A / B values filled by the app stay editable */bool computed=matching.Any(d=>!IsGeneralSuggestion(d))&&BackupMapping.Unit(item.Unit)!="ls";double? quantity=item.ManualQuantity??(computed||matching.Any(d=>d.ManualPriority>=1)?(double?)BackupMapping.FinalQuantity(matching,item.Unit)/* the app is the source of quantities except Progress Photographs (23 November 2026) */:item.WorkbookFallback);var row=new DataGridViewRow();row.CreateCells(boqGrid,item.Code,PayItemText.Display(item.Description),item.ManualInputText??(quantity.HasValue?quantity.Value.ToString("0.########",CultureInfo.InvariantCulture):""),item.Unit);if(sources.Count>0)row.DefaultCellStyle.Font=BoqItemFont;pendingRows.Add(row);row.Tag=item;string branch="item:"+item.Slot+":"+item.Signature;/* Windows: a cell set read-only on a detached row could not be made editable again, so the quantity cell is never locked first */bool quantityLocked=computed&&!item.ManualQuantity.HasValue&&item.ManualInputText==null;for(int c=0;c<row.Cells.Count;c++)if(c!=2)row.Cells[c].ReadOnly=true;if(quantityLocked)row.Cells[2].ReadOnly=true;row.Cells[2].Style.BackColor=quantityLocked?ModernUi.Soft:ModernUi.Input;row.Cells[2].ToolTipText=computed?"Computed from Tool Kit measurements.":suggested&&!item.ManualQuantity.HasValue?"Filled by the app (Part A / B). Type a quantity to change it; 0 removes the item.":"Enter manual quantity here. Zero clears quantity; blank removes the override.";AddBoqDemandRows(row,branch,item,sources,pendingRows);}
 boqGrid.Rows.AddRange(pendingRows.ToArray());/* Windows CI (19 November 2026): a quantity cell made editable while its row was not yet in the grid stayed read-only on
   Windows, so typed Part A / B quantities could not be entered; the state is applied again once the rows are in the grid (the cell
   colour records it) */for(int n=0;n<boqGrid.Rows.Count;n++){var added=boqGrid.Rows[n];/* indexer: the grid's own (unshared) row */if(!(added.Tag is BackupBillItem))continue;var q=added.Cells[2];bool editable=q.Style.BackColor.ToArgb()==ModernUi.Input.ToArgb();if(q.ReadOnly==editable)q.ReadOnly=!editable;}AddUnmappedBoqRows(unmapped);AddLegacyBoqRows();if(boqDisclosure!=null)boqDisclosure.Apply();var issues=WorksValidationIssues();boqStatus.ForeColor=issues.Count>0?Color.Firebrick:PowTheme.Teal;boqStatus.Text=backupBill.Count+" BACKUP pay items | computed quantities update here immediately"+(unmapped.Count>0?" | "+unmapped.Count+" source(s) need one-time mapping":"")+(issues.Count>0?" | Partial output; "+issues.Count+" input issue(s) listed below":"");foreach(var q in unmapped.Where(q=>!q.ManualOverride))boqStatusNotes.Add(new BoqStatusNote{Kind="Not mapped",Text=q.Description+" — "+q.Quantity.ToString("0.###",CultureInfo.InvariantCulture)+" "+q.Unit+" (double-click to map)",Demand=q});/* Owner (18 November 2026, BOQ without checkboxes / arrows and Status "OK"): checkboxes and expand arrows only
 appear on pay items that receive Tool Kit quantities. Say so instead of a bare OK when none are mapped. */
 if(!grouped.Values.Any(v=>v.Count>0)&&unmapped.Count==0)boqStatusNotes.Add(new BoqStatusNote{Kind="Info",Text=(HasMeasuredInputs()?"The Tool Kit quantities of this project are not mapped to any BACKUP pay item yet. Use Map BACKUP items.":"This project has no Tool Kit quantities yet (no worksheet rows entered or loaded). Quantities shown come from the BACKUP workbook.")+" The include checkbox and the expand arrow appear on a pay item once Tool Kit quantities are mapped to it."});
 UpdateIssuePanel(issues);}finally{boqGrid.AutoSizeRowsMode=rowSizing;boqGrid.ResumeLayout();paintingBackupBill=false;if(selectedId!=null&&selectedVisible){var row=boqGrid.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>r.Tag is BackupBillItem&&((BackupBillItem)r.Tag).Slot==selectedId);if(row!=null)boqGrid.CurrentCell=row.Cells[2];}scroll.Restore(boqGrid);}}
 void AddLegacyBoqRows(){if(plumbingLs==null)return;foreach(DataGridViewRow item in plumbingLs.Rows){if(item.IsNewRow||Cell(item,6)!=""||Cell(item,2)=="")continue;int n=boqGrid.Rows.Add("",Cell(item,2),Cell(item,3),Cell(item,5));var row=boqGrid.Rows[n];row.Tag=item;foreach(DataGridViewCell cell in row.Cells)cell.ReadOnly=true;row.Cells[2].ReadOnly=false;row.Cells[2].Style.BackColor=ModernUi.Input;}}
}
